import os

from ute_common_util.timeout import Timeout

from .logger import Logger
from .exception import ExecutionError
from .shell import Zipper, Shell, FileChecker


logger = Logger()


class Downloader(object):
    def __init__(self, connection, release_timeout=60):
        """
        :param Connection connection: Container for connection parameters.
        """
        self._connection = connection
        self._release_timeout = release_timeout

    def download(self, files, destination, unpack=False, timeout=900):
        """Download specified files to specified destination.

        :param list files:          List of absolute paths to files to download.
        :param string destination:  Path to directory or packed file (filename.tar.gz) where downloaded packed file
                                    should be stored.
        :param boolean unpack:      Downloaded content will be decompressed if unpack is set to True.
        :param integer timeout:     Timeout for whole download operation.

        :note: All source files will be removed if destination host or directory are different.
        :note: All actions are performed locally if files are available on local host.
        :note: Packed filename is a <SHA1 digest>.tar.gz if name is not provided as part of destination.
        """
        timeout = Timeout(timeout)
        FileChecker(self._connection).wait_until_files_released(files, timeout=self._release_timeout)
        if self._is_localhost():
            return LocalDownloader().run(files=files, destination=destination, unpack=unpack, timeout=timeout)
        return RemoteDownloader(self._connection).run(files=files, destination=destination, unpack=unpack,
                                                      timeout=timeout)

    def _is_localhost(self):
        local_uuid = Shell().system_uuid()
        remote_uuid = Shell(self._connection).system_uuid()
        return local_uuid == remote_uuid


class LocalDownloader(object):

    def __init__(self):
        self._connection = None

    def run(self, files, destination, unpack, timeout):
        """Runs download operation without SSH Connection."""
        logger.info('Download operation will be performed locally')
        Shell(self._connection).make_directory(destination=destination, timeout=timeout.time_left())
        if not unpack:
            Zipper(self._connection).compress_files(files=files, dest=destination, timeout=timeout.time_left())
            self._remove_files(files, timeout.time_left())
        else:
            self._move_files(files, destination, timeout)

    def _remove_files(self, files, timeout):
        Shell(self._connection).rm(path=' '.join(files), force=True, timeout=timeout)

    def _move_files(self, files, destination, timeout):
        if destination.endswith('tar.gz'):
            destination = os.path.dirname(destination)
        for single_file in files:
            if not self._is_same_file(single_file, destination, timeout.time_left()):
                Shell(self._connection).move_file(source=single_file, destination=destination,
                                                  timeout=timeout.time_left())

    def _is_same_file(self, filepath, destination, timeout):
        try:
            destination = os.path.join(destination, os.path.basename(filepath))
            source_info = Shell(self._connection).stat(path=filepath, timeout=timeout)
            destination_info = Shell(self._connection).stat(path=destination, timeout=timeout)
            return source_info == destination_info
        except ExecutionError:
            return False


class RemoteDownloader(object):
    def __init__(self, connection):
        self._connection = connection

    def run(self, files, destination, unpack, timeout):
        """Runs download operation via SSH connection."""
        Shell(self._connection).make_directory(destination=destination, timeout=timeout.time_left())
        logger.info('Download operation will be performed via SSH connection')
        with Zipper(self._connection) as zipper:
            zipped_file = zipper.compress_files(files=files, timeout=timeout.time_left())
            Shell(self._connection).copy_file(zipped_file, destination, timeout.time_left())
            if unpack:
                self._decompress_file(zipped_file, destination, timeout.time_left())
            else:
                self._remove_remote_files(files, timeout.time_left())

    def _decompress_file(self, zipped_file, destination, timeout):
        if not destination.endswith('tar.gz'):
            filename = os.path.basename(zipped_file)
            Zipper().decompress_file(os.path.join(destination, filename), timeout)
            Shell().rm(path=os.path.join(destination, filename), force=True, timeout=timeout)
        else:
            Zipper().decompress_file(destination, timeout)
            Shell().rm(path=destination, force=True, timeout=timeout)

    def _remove_remote_files(self, files, timeout):
        Shell(self._connection).rm(path=' '.join(files), force=True, timeout=timeout)
